draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 - 40 + 20 * Math.sin(t), H/2 + 10);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 + 40 - 20 * Math.sin(t), H/2 + 10);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 100);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 30 + 10 * Math.sin(t), H/2 + 20, 60, 30);

  ctx.restore();
}
